reference_solution:
def corpFlightBookings(bookings, n):
    diff = [0] * (n + 1)
    for first, last, seats in bookings:
        diff[first - 1] += seats
        diff[last] -= seats
    out, run = [], 0
    for i in range(n):
        run += diff[i]
        out.append(run)
    return out

brute_force_solution:
def corpFlightBookings(bookings, n):
    res = [0] * n
    for first, last, seats in bookings:
        for i in range(first - 1, last):
            res[i] += seats
    return res

